from jsonb_to_recordset($json$[{"id":"che-pe-161","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Sodium ion is smaller than a sodium atom because","options":["a 3p electron is added","the entire 3s electron has been removed","nuclear charge of Na⁺ is smaller","Na⁺ has one extra shell"],"answer_index":1,"explanation":"Na is [Ne] 3s¹; Na⁺ is a compact neon-like core with higher Zeff per electron.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-162","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among Li, Na, K and Rb, the atom with the largest covalent radius is","options":["lithium","sodium","potassium","rubidium"],"answer_index":3,"explanation":"Size increases down group 1 as extra shells are added; Rb is the heaviest of the four.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-163","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among Na, Mg, Al and Si, the smallest atomic radius belongs to","options":["sodium","magnesium","aluminium","silicon"],"answer_index":3,"explanation":"Across period 3, Zeff rises and size falls, so Si is the smallest of this set.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-164","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The correct order of ionic radii is","options":["Mg²⁺ > Na⁺ > F⁻ > O²⁻","O²⁻ > F⁻ > Na⁺ > Mg²⁺","Na⁺ > O²⁻ > F⁻ > Mg²⁺","F⁻ > O²⁻ > Mg²⁺ > Na⁺"],"answer_index":1,"explanation":"These four ions are isoelectronic (10 e⁻); radius falls as Z rises from 8 (O) to 12 (Mg).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-165","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Gallium has an atomic radius close to that of aluminium because of","options":["a sudden drop in nuclear charge","the intervening 3d contraction","lanthanoid contraction in period 4","the absence of a 4p subshell"],"answer_index":1,"explanation":"Poorly shielding 3d¹⁰ electrons raise Zeff on Ga and cancel the expected size increase down the group.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-166","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among the isoelectronic set S²⁻, Cl⁻, K⁺ and Ca²⁺, the smallest species is","options":["S²⁻","Cl⁻","K⁺","Ca²⁺"],"answer_index":3,"explanation":"All have 18 electrons; Ca²⁺ has the largest nuclear charge (Z = 20) and therefore the most contracted cloud.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-167","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The covalent radius of silicon is larger than that of carbon because silicon","options":["has fewer electrons","has one extra principal shell","has a greater Zeff in the same shell","is a halogen"],"answer_index":1,"explanation":"C is period 2 and Si is period 3; the added n = 3 shell makes Si larger.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-168","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The size order Li⁺ > Be²⁺ > B³⁺ holds because","options":["electron count rises along the series","nuclear charge rises while the electron count stays two","a new shell is added at each step","these ions are not isoelectronic"],"answer_index":1,"explanation":"All three are 1s² species; higher Z pulls the same two electrons closer.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-169","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Zirconium and hafnium have nearly identical atomic radii because of","options":["alkali-metal contraction","lanthanoid contraction","an extra 4s shell on Hf","a fall in Z from Zr to Hf"],"answer_index":1,"explanation":"The 14 poorly shielding 4f electrons inserted before Hf shrink it so that r(Hf) ≈ r(Zr).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-170","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fe²⁺ is larger than Fe³⁺ because removal of an extra electron","options":["adds a new shell","raises Zeff and shrinks the remaining 3d cloud","lowers the nuclear charge","converts iron into a noble gas"],"answer_index":1,"explanation":"Both ions are iron, but Fe³⁺ has fewer electrons and a higher charge density, so it is the smaller cation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-171","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Ionisation enthalpy is the energy needed to remove an electron from an isolated gaseous atom in its","options":["first excited state only","ground state","metallic crystal","aqueous solution"],"answer_index":1,"explanation":"The textbook definition uses the ground-state gaseous atom: M(g) → M⁺(g) + e⁻.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-172","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The first ionisation enthalpy refers to removal of an electron from the","options":["uninegative ion","neutral gaseous atom","dipositive cation","solid metal lattice"],"answer_index":1,"explanation":"IE₁ is for M(g); IE₂ is for M⁺(g), and so on.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
